        /**
         * 非必需参数：指示模型是否返回生成每个令牌时的对数概率，以及在完成时返回的标记列表和相应的对数概率。默认为null，表示不返回对数概率。
         */
        private Integer logProbs;

        /**
         * 非必需参数：指示API是否将提示包含在响应中。默认为true，表示将提示包含在响应中。
         */
        private boolean echo;

        /**
